static bool validate_scalar_one(const unsigned char *bytes, size_t length,
                                size_t *index) {
  size_t i = *index;
  const unsigned char first = bytes[i++];
  if (first < 0x80) {
    *index = i;
    return true;
  }

  if (first >= 0xC2 && first <= 0xDF) {
    if (length - i < 1) return false;
    const unsigned char second = bytes[i++];
    if ((second & 0xC0) != 0x80) return false;
  } else if (first >= 0xE0 && first <= 0xEF) {
    if (length - i < 2) return false;
    const unsigned char second = bytes[i++];
    const unsigned char third = bytes[i++];
    if ((second & 0xC0) != 0x80 || (third & 0xC0) != 0x80 ||
        (first == 0xE0 && second < 0xA0) ||
        (first == 0xED && second >= 0xA0)) {
      return false;
    }
  } else if (first >= 0xF0 && first <= 0xF4) {
    if (length - i < 3) return false;
    const unsigned char second = bytes[i++];
    const unsigned char third = bytes[i++];
    const unsigned char fourth = bytes[i++];
    if ((second & 0xC0) != 0x80 || (third & 0xC0) != 0x80 ||
        (fourth & 0xC0) != 0x80 ||
        (first == 0xF0 && second < 0x90) ||
        (first == 0xF4 && second > 0x8F)) {
      return false;
    }
  } else {
    return false;
  }

  *index = i;
  return true;
}

