static inline __m128i utf8_lead2(__m128i mapped) {
  return _mm_and_si128(_mm_cmpgt_epi8(mapped, _mm_set1_epi8(65)),
                       _mm_cmpgt_epi8(_mm_set1_epi8(96), mapped));
}

static inline __m128i utf8_lead3(__m128i mapped) {
  return _mm_and_si128(_mm_cmpgt_epi8(mapped, _mm_set1_epi8(95)),
                       _mm_cmpgt_epi8(_mm_set1_epi8(112), mapped));
