  if (index == length) return true;
  const size_t vector_start = index;

#if defined(__SSE2__)
  const __m128i continuation_bits = _mm_set1_epi8(-64);
  const __m128i continuation_value = _mm_set1_epi8(-128);
  const __m128i zero = _mm_setzero_si128();

  while (length - index >= 16) {
    const __m128i current = _mm_loadu_si128(
