    const __m128i previous2 = _mm_loadu_si128(
        reinterpret_cast<const __m128i *>(bytes + index - 2));
    const __m128i previous3 = _mm_loadu_si128(
        reinterpret_cast<const __m128i *>(bytes + index - 3));

    const __m128i mapped = utf8_mapped(current);
    const __m128i mapped1 = utf8_mapped(previous1);
    const __m128i mapped2 = utf8_mapped(previous2);
    const __m128i mapped3 = utf8_mapped(previous3);

