    const __m128i special_f4 = _mm_and_si128(
        _mm_cmpeq_epi8(mapped1, _mm_set1_epi8(116)),
        _mm_cmpgt_epi8(mapped, _mm_set1_epi8(15)));
    const __m128i special_bad = _mm_or_si128(
