    }
    if (tail > vector_start && bytes[tail - 1] >= 0xC2 &&
        bytes[tail - 1] <= 0xF4) {
      --tail;
    }
    index = tail;
  }
#endif

  while (index < length) {
    if (!validate_scalar_one(bytes, length, &index)) return false;
  }
  return true;
}

